\title{Winning on the Hilbert Board:\\ King Escape in Every Dimension}
\author{Aristotle}
\date{2026-07-12}

\begin{document}
\maketitle

\begin{abstract}
We lift the theory of infinite-board chess from the classical plane $\Z^2$ to the
$d$-dimensional \emph{Hilbert board} $\Z^{d+2}$, the natural setting for
``infinite-dimensional chess.'' We prove that against a lone rook the king
possesses an explicit safe king-move in every dimension, and hence an infinite
legal escape run; that a lone rook can never checkmate; and that any finite army
of rooks leaves infinitely many completely unattacked squares. Recasting the
endgame as a pursuit game, we show that the lone-rook king's position is
\emph{not accessible} for the safe-move relation, so it carries no ordinal game
value---the transfinite signature of an unbreakable fortress---uniformly across
all dimensions. Finally we establish the sharp boundary: in a \emph{single}
dimension a rook attacks every other square, and two mutually defending rooks do
checkmate the king, a phenomenon impossible in dimension $\ge 2$. The sole
structural ingredient throughout is the existence of two distinct coordinate
axes; the entire fortress is therefore a single theorem schema valid for every
$d \ge 0$ and collapsing exactly in dimension one.
\end{abstract}

\section{Introduction}

Infinite-board chess replaces the bounded $8\times 8$ grid with an unbounded
lattice, removing the edge effects that drive classical endgame theory. On the
finite board the standard mating techniques rely essentially on herding the
defender into a corner. On an edgeless board there are no corners, and the
natural question becomes: which finite piece configurations still force mate, and
which leave the defending king an escape?

We study the cleanest instance---the lone rook against a bare king---in a setting
that has received little attention: \emph{arbitrarily many spatial dimensions}.
The $d$-dimensional Hilbert board is $\Z^{d+2}$, so at least two coordinate axes
are always present. Our central finding is that adding dimensions only
\emph{helps} the fleeing king. The lone-rook fortress---a one-step escape, an
infinite escape run, and the transfinite inaccessibility of the king's
position---survives verbatim into every dimension, and collapses only when the
board is degenerate (dimension one).

\paragraph{Contributions.}
(1) An explicit one-move escape against a lone rook in every dimension
(Section~\ref{sec:escape}); (2) an infinite escape run
(Section~\ref{sec:run}); (3) no lone-rook mate in any dimension
(Section~\ref{sec:nomate}); (4) infinitely many safe squares against any finite
army (Section~\ref{sec:cover}); (5) no ordinal game value---the king's position
is not accessible for the pursuit relation (Section~\ref{sec:ordinal}); (6) the
sharp boundary---two mutually defending rooks mate on the one-dimensional line
(Section~\ref{sec:boundary}).

\section{The model}

Fix a dimension parameter $d \in \N$.

\begin{definition}[Board]
A \emph{square} of the $(d+2)$-dimensional board is a function assigning an
integer to each of $d+2$ axes,
\[
  \Sq(d) := \{\, s : \{0,1,\dots,d+1\} \to \Z \,\} \;\cong\; \Z^{d+2}.
\]
We write $s_i$ for the $i$-th coordinate. The classical plane is $d=0$; ordinary
space is $d=1$.
\end{definition}

\begin{definition}[King adjacency]
Squares $p,q$ are \emph{king-adjacent}, $p \sim q$, when $p \neq q$ and
$|p_i - q_i| \le 1$ for all $i$. This is the punctured Chebyshev unit ball; a
king has $3^{d+2}-1$ neighbours.
\end{definition}

\begin{definition}[Rook attack]
A rook on $r$ \emph{attacks} $s$, $r \Rightarrow s$, when $s \neq r$ and there is
an axis $j$ with $s_i = r_i$ for all $i \neq j$; i.e.\ $s$ lies on the
axis-parallel line through $r$. A rook does not attack its own square, so an
undefended rook may be captured.
\end{definition}

\begin{definition}[Army attack and checkmate]
A finite army $R \subseteq \Sq(d)$ \emph{attacks} $s$ when some $r \in R$ attacks
$s$. The army $R$ \emph{checkmates} the king at $k$ when $R$ attacks $k$ and
$R$ attacks every $s \sim k$.
\end{definition}

\begin{lemma}[Two distinct axes]\label{lem:axes}
For every $d \ge 0$ the index set $\{0,\dots,d+1\}$ has at least two elements; in
particular $0 \neq 1$, and for any axis $j$ there is an axis $i \neq j$.
\end{lemma}

\begin{proof}
Immediate, since $d+2 \ge 2$.
\end{proof}

\section{The single-rook escape map}\label{sec:escape}

\begin{definition}[Escape coordinate]
For integers $a$ (king) and $c$ (rook) set
\[
  \esc(a,c) := \begin{cases} a-1, & c = a+1,\\ a+1, & \text{otherwise.}\end{cases}
\]
\end{definition}

\begin{lemma}\label{lem:esc}
For all $a,c$: (i) $\esc(a,c) \neq c$; (ii) $\esc(a,c) \neq a$; (iii)
$|\esc(a,c) - a| \le 1$.
\end{lemma}

\begin{proof}
Case split on $c = a+1$. In both branches $\esc(a,c) \in \{a-1,a+1\}$, giving
(ii) and (iii). For (i): if $c=a+1$ then $\esc = a-1 \neq a+1 = c$; otherwise
$\esc = a+1$ and $c \neq a+1$ by the branch condition.
\end{proof}

\begin{definition}[King escape step]
Given rook $r$ and king $p$, define $g(r,p)_i := \esc(p_i, r_i)$ for each axis
$i$: the king steps away from the rook in every coordinate at once.
\end{definition}

\begin{theorem}[One-move escape]\label{thm:escape}
For every $d \ge 0$ and all $r,p \in \Sq(d)$, the square $g(r,p)$ is king-adjacent
to $p$ and is not attacked by $r$.
\end{theorem}

\begin{proof}
\emph{Adjacency.} By Lemma~\ref{lem:esc}(iii), $|g(r,p)_i - p_i| \le 1$ for all
$i$; and $g(r,p) \neq p$ since they differ in coordinate $0$ by
Lemma~\ref{lem:esc}(ii). Hence $p \sim g(r,p)$.

\emph{Safety.} If $r \Rightarrow g(r,p)$, there is an axis $j$ with
$g(r,p)_i = r_i$ for all $i \neq j$. By Lemma~\ref{lem:axes} choose $i \neq j$;
then $\esc(p_i, r_i) = r_i$, contradicting Lemma~\ref{lem:esc}(i).
\end{proof}

\begin{remark}
The proof consults the dimension only through the existence of a second axis
$i \neq j$. This is the sole structural ingredient of the entire development.
\end{remark}

\section{The infinite escape run}\label{sec:run}

\begin{theorem}[Eternal escape]\label{thm:run}
For every $d \ge 0$ and all $r,k \in \Sq(d)$ there is a sequence
$f : \N \to \Sq(d)$ with $f_0 = k$ and, for all $n$, $f_n \sim f_{n+1}$ and
$\neg\,(r \Rightarrow f_{n+1})$.
\end{theorem}

\begin{proof}
Take $f_n := g(r,\cdot)^{[n]}(k)$, the $n$-fold iterate applied to $k$. Then
$f_{n+1} = g(r,f_n)$, and Theorem~\ref{thm:escape} at $p = f_n$ gives both
$f_n \sim f_{n+1}$ and $\neg\,(r \Rightarrow f_{n+1})$.
\end{proof}

\section{Finitely many rooks cannot cover the board}\label{sec:cover}

\begin{lemma}[Safe-square core]\label{lem:safe}
Let $R$ be a finite army. If $x \notin \{r_0 : r \in R\}$ and
$y \notin \{r_1 : r \in R\}$, then the square $s$ with $s_0 = x$, $s_1 = y$, and
$s_i = 0$ for $i \ge 2$ is unattacked by $R$.
\end{lemma}

\begin{proof}
Suppose $r \in R$ attacks $s$ along axis $j$. If $j \neq 0$, then $s_0 = r_0$,
i.e.\ $x = r_0$, contradicting the choice of $x$. If $j = 0$, then $1 \neq j$ (as
$0 \neq 1$ by Lemma~\ref{lem:axes}), so $s_1 = r_1$, i.e.\ $y = r_1$,
contradicting the choice of $y$.
\end{proof}

\begin{theorem}[A safe square exists]\label{thm:safeexists}
For every $d \ge 0$ and every finite army $R$ there is a square unattacked by $R$.
\end{theorem}

\begin{proof}
The sets $\{r_0 : r \in R\}$ and $\{r_1 : r \in R\}$ are finite subsets of the
infinite set $\Z$; choose $x,y$ avoiding them and apply Lemma~\ref{lem:safe}.
\end{proof}

\begin{theorem}[Infinitely many safe squares]\label{thm:infsafe}
For every finite army $R$ the set $\{ s : \neg\, R \Rightarrow s \}$ is infinite.
\end{theorem}

\begin{proof}
Fix $y \notin \{r_1 : r \in R\}$. The map $t \mapsto (t,y,0,\dots,0)$ is
injective and, by Lemma~\ref{lem:safe}, sends every $t \notin \{r_0 : r \in R\}$
to a safe square. The complement of the finite set $\{r_0 : r \in R\}$ in $\Z$ is
infinite, so its injective image is an infinite set of safe squares.
\end{proof}

\section{The lone rook never mates}\label{sec:nomate}

\begin{theorem}[No lone-rook mate]\label{thm:nomate}
For every $d \ge 0$ and all $r,k \in \Sq(d)$, the singleton army $\{r\}$ does not
checkmate $k$.
\end{theorem}

\begin{proof}
If it did, every square adjacent to $k$ would be attacked by $r$. But by
Theorem~\ref{thm:escape} the square $g(r,k)$ is adjacent to $k$ and not attacked
by $r$---a contradiction.
\end{proof}

\section{Ordinal game value: the king is inaccessible}\label{sec:ordinal}

\begin{definition}[Safe king step]
Against a rook $r$, the king may step from $p$ to $q$, written
$\KingStep_r(p,q)$, when $p \sim q$ and $\neg\,(r \Rightarrow q)$.
\end{definition}

A position from which the pursuit must terminate is exactly one that is
\emph{accessible} (well-founded) for the safe-step relation; its accessibility
rank is an ordinal---the game value. Infinite branching is why the rank can be
transfinite.

\begin{definition}[Attacker wins]
The attacker wins from $k$ when $k$ is accessible:
$\mathrm{AttackerWins}(r,k) := \Acc\big(\lambda\,q\,p.\ \KingStep_r(p,q)\big)(k)$.
\end{definition}

\begin{lemma}[Infinite descent blocks accessibility]\label{lem:descent}
If $f : \N \to \alpha$ satisfies $\mathrm{rel}(f_{n+1},f_n)$ for all $n$, then
$f_0$ is not accessible for $\mathrm{rel}$.
\end{lemma}

\begin{proof}
By induction on the accessibility predicate, no accessible element can equal any
$f_n$: if $x$ is accessible and $x = f_n$, then $f_{n+1}$ is a predecessor of $x$
and hence accessible, and the induction hypothesis applied to $f_{n+1} = f_{n+1}$
gives a contradiction. Thus $f_0 = f_0$ cannot be accessible.
\end{proof}

\begin{theorem}[No ordinal game value]\label{thm:noordinal}
For every $d \ge 0$ and all $r,k$, the position is not accessible:
$\neg\,\mathrm{AttackerWins}(r,k)$. The lone-rook endgame carries no ordinal
game value, uniformly in the dimension.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:run} there is an escape sequence $f$ with $f_0 = k$ and
$\KingStep_r(f_n,f_{n+1})$ for all $n$---an infinite descending chain for the
safe-step relation. Apply Lemma~\ref{lem:descent}.
\end{proof}

\section{The boundary: two rooks mate on the line}\label{sec:boundary}

Model the one-dimensional board as $\Z$. With a single axis, ``agree in all but
one coordinate'' is vacuous, so a rook attacks every square except its own.

\begin{definition}
On $\Z$: $p,q$ are adjacent when $p \neq q$ and $|p-q| \le 1$; a rook $r$ attacks
$s$ iff $s \neq r$; and $R$ checkmates $k$ when $R$ attacks $k$ and attacks every
adjacent square.
\end{definition}

\begin{theorem}[Two rooks mate on the line]\label{thm:line}
On $\Z$, the king at $k$ is checkmated by $\{k-1,\ k+1\}$.
\end{theorem}

\begin{proof}
The rook at $k-1$ attacks $k$, so the king is in check. Its only adjacent squares
are $k-1$ and $k+1$: the square $k-1$ is attacked by the rook at $k+1$, and $k+1$
by the rook at $k-1$. Both flanking rooks are mutually defended, so neither can be
captured. Hence checkmate.
\end{proof}

This is impossible in dimension $\ge 2$, where the king can always sidestep along
a second axis into a square both rooks miss. The collapse of the fortress is a
strictly one-dimensional effect, pinpointing the threshold at ``two distinct
axes.''

\section{Discussion}

Beneath the chess vocabulary the results concern covering a lattice by
axis-parallel lines: a rook is a line, check is membership in a line, mate is a
covering of a Chebyshev ball by lines, and escape is the failure of finitely many
lines to cover a two-dimensional or higher neighbourhood. The central
phenomenon---finite linear firepower cannot corner a fugitive with two or more
directions of flight---is a robust geometric truth. Three features stand out: the
escape is \emph{explicit} (a formula $g(r,p)$); it is \emph{dimensionally robust}
(the proofs consult the dimension only through Lemma~\ref{lem:axes}); and its
honest invariant is a transfinite one---the accessibility rank of the pursuit
relation, which for the lone-rook fortress does not exist.

\section{Future work}

\paragraph{Material threshold vs.\ dimension.} On $\Z^{d+2}$ the least number of
rooks forcing mate appears to be a strictly increasing $m(d)$ with $m(0)=3$ and
$m(d) \to \infty$: a mate must cover the king and all $3^{d+2}-1$ neighbours by
axis-lines, a Hamming-ball line-cover number that should diverge.

\paragraph{Realising ordinal values.} For every countable ordinal $\alpha <
\omega^\omega$ one expects a finite configuration with forced-mate game value
exactly $\alpha$, independent of $d$, since the winning-tree calculus is
dimension-agnostic.

\paragraph{Genuinely infinite-dimensional boards.} On finitely supported integer
sequences, a finite rook army should still leave infinitely many unattacked
squares and a lone rook should still never mate: every obstruction used only
``two distinct axes.''

\paragraph{Escape complexity.} Against $n$ adversarial rooks, quantify the optimal
growth rate of the king's safe-run as a function of army size and dimension.

\begin{table}[h]
\centering
\begin{tabular}{lll}
\toprule
Result & Statement & Range \\
\midrule
One-move escape (Thm~\ref{thm:escape}) & $g(r,p)$ adjacent, unattacked & all $d \ge 0$ \\
Eternal escape (Thm~\ref{thm:run}) & infinite safe king run & all $d \ge 0$ \\
Safe squares (Thm~\ref{thm:safeexists},~\ref{thm:infsafe}) & $\infty$ many safe squares & all $d \ge 0$ \\
No lone mate (Thm~\ref{thm:nomate}) & one rook never mates & all $d \ge 0$ \\
No ordinal value (Thm~\ref{thm:noordinal}) & king inaccessible & all $d \ge 0$ \\
Line mate (Thm~\ref{thm:line}) & two rooks mate on $\Z$ & dimension one \\
\bottomrule
\end{tabular}
\end{table}

\end{document}

