"""Demo 1: the explicit escape run works identically in every dimension."""
from __future__ import annotations
from typing import List, Tuple

Square = Tuple[int, ...]


def esc_coord(a: int, c: int) -> int:
    return a - 1 if c == a + 1 else a + 1


def king_escape_step(rook: Square, king: Square) -> Square:
    return tuple(esc_coord(p, r) for p, r in zip(king, rook))


def king_adjacent(p: Square, q: Square) -> bool:
    return p != q and all(abs(a - b) <= 1 for a, b in zip(p, q))


def rook_attacks(r: Square, s: Square) -> bool:
    return s != r and sum(1 for a, b in zip(r, s) if a != b) == 1


def escape_run(rook: Square, king: Square, steps: int) -> List[Square]:
    run = [king]
    cur = king
    for _ in range(steps):
        cur = king_escape_step(rook, cur)
        run.append(cur)
    return run


def main() -> None:
    for dim in (2, 3, 4, 7):
        rook: Square = tuple(0 for _ in range(dim))
        king: Square = tuple(1 for _ in range(dim))
        run = escape_run(rook, king, 10)
        legal = all(king_adjacent(run[n], run[n + 1]) for n in range(len(run) - 1))
        safe = all(not rook_attacks(rook, run[n + 1]) for n in range(len(run) - 1))
        print(f"dim {dim}: 10-move run legal={legal}, never-in-check={safe}")


if __name__ == "__main__":
    main()

"""Demo 2: safe squares have positive density -- lines cannot cover a plane."""
from __future__ import annotations
from typing import List, Tuple

Square = Tuple[int, int]


def rook_attacks(r: Square, s: Square) -> bool:
    return s != r and sum(1 for a, b in zip(r, s) if a != b) == 1


def attacked_by(army: List[Square], s: Square) -> bool:
    return any(rook_attacks(r, s) for r in army)


def main() -> None:
    armies = [
        [(2, 3)],
        [(2, 3), (5, 5), (7, 1)],
        [(i, (3 * i) % 11) for i in range(8)],
    ]
    window = 20
    for army in armies:
        total = window * window
        safe = sum(
            1
            for x in range(window)
            for y in range(window)
            if not attacked_by(army, (x, y))
        )
        rows, cols = len({r[1] for r in army}), len({r[0] for r in army})
        # rough theoretical lower bound: (window - cols) * (window - rows)
        bound = max(0, window - cols) * max(0, window - rows)
        print(f"{len(army)} rooks: {safe}/{total} squares safe in a "
              f"{window}x{window} window (>= {bound} guaranteed by construction)")


if __name__ == "__main__":
    main()

"""Demo 3: the dimensional boundary -- no mate on the plane, mate on the line."""
from __future__ import annotations
from itertools import product
from typing import List, Sequence, Tuple

Square = Tuple[int, ...]


def neighbours(p: Square) -> List[Square]:
    out = []
    for d in product((-1, 0, 1), repeat=len(p)):
        if any(d):
            out.append(tuple(a + x for a, x in zip(p, d)))
    return out


def rook_attacks(r: Square, s: Square) -> bool:
    return s != r and sum(1 for a, b in zip(r, s) if a != b) == 1


def attacked_by(army: Sequence[Square], s: Square) -> bool:
    return any(rook_attacks(r, s) for r in army)


def checkmated(army: Sequence[Square], k: Square) -> bool:
    return attacked_by(army, k) and all(attacked_by(army, s) for s in neighbours(k))


def rook_attacks_line(r: int, s: int) -> bool:
    return s != r


def checkmated_line(army: Sequence[int], k: int) -> bool:
    if not any(rook_attacks_line(r, k) for r in army):
        return False
    return all(any(rook_attacks_line(r, s) for r in army) for s in (k - 1, k + 1))


def main() -> None:
    # Plane: no single rook mates, checked exhaustively over a window.
    king = (0, 0)
    any_mate = any(
        checkmated([(rx, ry)], king)
        for rx in range(-3, 4)
        for ry in range(-3, 4)
    )
    print(f"plane Z^2: does ANY lone rook (window) mate king at origin? {any_mate}")

    # Space: same check in 3-D.
    any_mate3 = any(
        checkmated([(a, b, c)], (0, 0, 0))
        for a in range(-2, 3)
        for b in range(-2, 3)
        for c in range(-2, 3)
    )
    print(f"space Z^3: does ANY lone rook (window) mate king at origin? {any_mate3}")

    # Line: two flanking rooks always mate.
    for k in (-4, 0, 9):
        print(f"line Z: rooks {{{k-1}, {k+1}}} mate king at {k}? "
              f"{checkmated_line([k - 1, k + 1], k)}")


if __name__ == "__main__":
    main()

