function KingEscapeStep(rook r, king p):
    for each axis i in 0 .. n-1:
        if r[i] == p[i] + 1:
            q[i] <- p[i] - 1
        else:
            q[i] <- p[i] + 1
    return q
# q is king-adjacent to p and unattacked by r whenever n >= 2

function FindSafeSquare(army R, dimension n):
    X <- { r[0] : r in R }
    Y <- { r[1] : r in R }
    x <- least nonnegative integer not in X
    y <- least nonnegative integer not in Y
    return (x, y, 0, ..., 0)   # length n
# differs from every rook in two axes => unattacked

